 [{"type": "text", "text": "八折 = 0.8 不是 0.2"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "满减和打折的计算方式搞混"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "打折促销题的核心是\"实际售价 = 标价 * 折扣率\"。注意折扣是乘不是减。"}]}]}]}$$ AS jsonb), NULL, '数量关系-经济利润问题-打折促销的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "经济利润问题", "打折促销"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_profit_discount", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
